/**
 * ISO-59020 regulation-table seed builder (Plan 3 Task 21, 2026-09-18).
 *
 * SR-1: every seeded cell and every `verbatim_quote` was read in this session
 * from the English plain-text transcript `Desktop\Ciruclar economy, sustanability
 * and water test\ISO 59020\ISO-59020-Unlocked.txt` (ISO 59020:2024(en), first
 * edition 2024-05; 4131 lines; the `.pdf` siblings are NOT sources). The spans
 * live in `regulation-tables-quotes-iso59020.ts` (generated by line range, never
 * retyped); the line range is in each span's name. A plain-text transcript is a
 * VC-grade source — the table ships `verification_status: 'imported_unverified'`
 * (controller rule: txt = VC; amendment F: the five line-end hyphenations in the
 * printed cells are recorded as iso59020-U-1, nothing is upgraded).
 * Verified by `scripts/regulation-tables/verify-regulation-tables.ts iso59020 "<transcript>"`.
 * Emitted as `20260917102100_regulation_tables_seed_iso59020.sql` (no earlier
 * ISO-59020 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "First edition" / "2024-05" (L8–L9); prod
 * `standards.version` is "2024 (First edition 2024-05)" (read-only 2026-09-18)
 * → token `'2024'`.
 *
 * The standard prints ONE classification table (Table 3, L1081–L1148, over two
 * pages: 13 core circularity indicators × category / Mandatory-Optional / name /
 * summary description / additional information) and no numeric constant. The
 * plain-text layout prints the columns side by side, so a cell is split over
 * several lines and interleaved with the neighbouring columns — every cell is
 * therefore asserted as printed FRAGMENTS (one per transcript line, whitespace
 * collapsed) inside the row's line span; the seeded cell is the fragments joined
 * by a space. The merged category cell ("Resource / Inflows", "Resource /
 * outflows", "Energy", "Water", "Economic") is printed once per group and is
 * asserted against the whole-table span.
 *
 * Key tokens (G-A3 / D-1): the row keys are EXACTLY prod's `selected_core_indicator`
 * enum `value` strings (13, captured 2026-09-18 — `A.2.2_reused_content_inflow` …
 * `A.6.3_resource_intensity_index`); `category_token` carries the prod
 * `indicator_category` token of the printed category (resource_inflow /
 * resource_outflow / energy / water / economic — a structural mapping column,
 * iso59020-J-3), `category` the printed words.
 *
 * Unreadable / de-hyphenated cells (all recorded, nothing corrected silently):
 *   - iso59020-U-1: five line-end hyphenations inside printed cells are joined to
 *     the word the same column prints elsewhere — "sustainably pro-/duced" (L1094–L1095),
 *     "aver-/age" (L1098–L1099), "Recovers re-/source value" (L1107–L1108),
 *     "recir-/culation" (L1110–L1111), "in ac-/cordance" (L1135–L1137). The
 *     `printed` fragments keep the hyphen so the assertion is against the page.
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-iso59020';

const STD = 'ISO-59020';
export const ISO59020_EDITION = '2024';
const ED = ISO59020_EDITION;
const STATUS = 'imported_unverified' as const; // VC source (plain txt) — U-1 hyphenations

/** Whitespace-collapsed containment: the layout prints cells with runs of spaces / line breaks. */
export const collapse = (s: string): string => s.replace(/\s+/g, ' ').trim();
/** Build-time SR-1 guard: every seeded cell fragment must be printed inside the named span. */
function inSpan(quote: string, cell: string, where: string): void {
  if (!collapse(quote).includes(collapse(cell))) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}

/** Prod `indicator_category` tokens (captured 2026-09-18) for the five printed category cells. */
export const CATEGORY_TOKENS = {
  'Resource Inflows': 'resource_inflow',
  'Resource outflows': 'resource_outflow',
  Energy: 'energy',
  Water: 'water',
  Economic: 'economic',
} as const;
export type Table3Category = keyof typeof CATEGORY_TOKENS;

type Table3Row = {
  /** prod `selected_core_indicator` token */
  key: string;
  category: Table3Category;
  /** printed fragments of the merged category cell (asserted against the whole-table span) */
  category_printed: string[];
  mandatory: 'Mandatory' | 'Optional';
  clause: string;
  /** printed fragments of the indicator name, one per line, joined by a space */
  name: string[];
  /** printed fragments of the summary description, one per line (hyphenated where printed — U-1) */
  description: string[];
  /** the de-hyphenated description (null when no hyphenation is printed) */
  description_joined?: string;
  /** printed fragments of the additional-information cell */
  principle: string[];
  principle_joined?: string;
  quote: string;
};

