// ---------------------------------------------------------------------------
// TABLE3 — Table 3 "Core circularity indicators" (L1081–L1148): 13 rows keyed on the prod
// `selected_core_indicator` tokens. Read by the ISO-59020-04 `indicators` register (lookup_key +
// lookup_value fills, the per-row `mandatory_flag` / `ok` badges) and by the -04 equations.
// Policy: L1068–L1071 "shall be quantified and fully balanced with the use of the mandatory
// indicators … If a core circularity indicator is not applicable, the organization should explain why
// and can count the indicator value as zero" ⇒ locked (the mandatory flag is not an engineer choice;
// N/A is a per-row declaration with a justification, not an override of the table).
// ---------------------------------------------------------------------------
export function table3AsTable(): RegulationTable {
  const rows: RegulationRow[] = TABLE3_ROWS.map((r, i) => {
    const where = `TABLE3 ${r.key}`;
    inSpan(r.quote, r.mandatory, `${where} mandatory`);
    for (const f of r.name) inSpan(r.quote, f, `${where} name`);
    for (const f of r.description) inSpan(r.quote, f, `${where} description`);
    for (const f of r.principle) inSpan(r.quote, f, `${where} principle`);
    for (const f of r.category_printed) inSpan(Q.L1081_1148, f, `${where} category`);
    inSpan(r.quote, r.clause, `${where} clause`);
    const name = r.name.join(' ');
    if (!name.startsWith(`${r.clause} `)) throw new Error(`${where}: name does not start with its clause`);
    return {
      row_key: r.key, keys: { indicator: r.key }, group_label: r.category, label_de: name, order_index: i,
      values: {
        category: r.category,
        category_token: CATEGORY_TOKENS[r.category],
        mandatory_optional: r.mandatory,
        mandatory: r.mandatory === 'Mandatory',
        clause: r.clause,
        name,
        description: r.description_joined ?? r.description.join(' '),
        principle: r.principle_joined ?? r.principle.join(' '),
      },
      verbatim_quote: r.quote,
    };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLE3', title_de: 'Tabelle 3 — Kern-Zirkularitätsindikatoren (Kategorie, verbindlich/optional, Indikator, Kurzbeschreibung, Zusatzinformation)', clause_reference: '§7.3.1, Table 3', page_ref: null,
    key_columns: ['indicator'],
    value_columns: [
      { name: 'category', type: 'string' },
      { name: 'category_token', type: 'enum', values: [...new Set(Object.values(CATEGORY_TOKENS))] },
      { name: 'mandatory_optional', type: 'enum', values: ['Mandatory', 'Optional'] },
      { name: 'mandatory', type: 'boolean' },
      { name: 'clause', type: 'string' },
      { name: 'name', type: 'string' },
      { name: 'description', type: 'string' },
      { name: 'principle', type: 'string' },
    ],
    override_policy: 'locked',
    override_quote: Q.L1068_1071,
    verification_status: STATUS, rows };
}

/** The live ISO-59020 set (one table). */
export function iso59020SeedTables(): RegulationTable[] {
  return [table3AsTable()];
}
